/** One provider from the Terraform Registry (generated by scripts/catalog.ts). */
export interface CatalogProvider {
  id: string;
  name: string;
  /** Terraform source address, e.g. "hashicorp/aws". */
  terraform: string;
  tier: "official" | "partner" | "community";
  description: string;
  downloads: number;
  repository: string;
  /** Hand-picked developer service rather than a download-ranked registry entry. */
  curated: boolean;
}
